grid = [
    [8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 5, 8, 8],
    [8, 5, 5, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 8, 8, 8, 8, 8, 8, 5, 8, 8, 5, 8, 8, 8]
]

# Find positions of 5s
positions_of_5 = []
for r in range(3):
    for c in range(27):
        if grid[r][c] == 5:
            positions_of_5.append((r, c))

print("Positions of 5s:", positions_of_5)

# Group by row
by_row = {}
for r, c in positions_of_5:
    by_row.setdefault(r, []).append(c)

print("By row:", by_row)

# Check if any form patterns horizontally
for r in range(3):
    if r in by_row:
        sorted_cols = sorted(by_row[r])
        print(f"Row {r}: 5s at columns {sorted_cols}")
        # Check gaps between consecutive 5s in same row
        for i in range(len(sorted_cols)-1):
            gap = sorted_cols[i+1] - sorted_cols[i] - 1
            print(f"  Gap after col {sorted_cols[i]}: {gap} cells")

